func (this *TableItem) SetImageIndexImage(index int32, imageLike ImageLike) {
	var image *Image
	if imageLike != nil {
		image = imageLike.AsImage()
	}
	_ = image
	this.CheckWidget()
	if image != (nil) && image.impl.isDisposed_() {
		this.Error(ERROR_INVALID_ARGUMENT)
	}
	if image != (nil) && image.Type == ICON {
		if image.Equals(this._getImage(index)) {
			return
		}
	}
	var count int32 = int32(math.Max(float64(1), float64(this.parent.GetColumnCount())))
	if 0 > index || index > count-1 {
		return
	}
	var pixbuf int64 = int64(0)
	var surface int64 = int64(0)
	if image != (nil) {
		var imageList *ImageList = this.parent.imageList
		if imageList == (nil) {
			this.parent.imageList = NewImageList()
			imageList = this.parent.imageList
		}
		var imageIndex int32 = imageList.IndexOf(image)
		var tempSurface int64 = ImageListConvertSurface(image)
		gtk.CairoCairo_surface_destroy(tempSurface)
		if imageIndex == -1 {
			imageIndex = imageList.Add(image)
		}
		surface = imageList.GetSurface(imageIndex)
		pixbuf = ImageListCreatePixbuf(surface)
	}
	var parentHandle int64 = this.parent.Handle
	var column int64 = gtk.GTKGtk_tree_view_get_column(parentHandle, index)
	var pixbufRenderer int64 = this.parent.GetPixbufRenderer(column)
	var currentWidth []int32 = make([]int32, 1)
	var currentHeight []int32 = make([]int32, 1)
	gtk.GTKGtk_cell_renderer_get_fixed_size(pixbufRenderer, currentWidth, currentHeight)
	if !this.parent.pixbufSizeSet {
		if image != (nil) {
			var iWidth int32 = image.GetBounds().Width
			var iHeight int32 = image.GetBounds().Height
			if iWidth > currentWidth[0] || iHeight > currentHeight[0] {
				gtk.GTKGtk_cell_renderer_set_fixed_size(pixbufRenderer, iWidth, iHeight)
				this.parent.pixbufHeight = iHeight
				this.parent.pixbufWidth = iWidth
				this.parent.pixbufSizeSet = true
			}
		}
	} else {
		if this.parent.pixbufWidth > int32(math.Max(float64(currentWidth[0]), float64(0))) || this.parent.pixbufHeight > int32(math.Max(float64(currentHeight[0]), float64(0))) {
			gtk.GTKGtk_cell_renderer_set_fixed_size(pixbufRenderer, this.parent.pixbufWidth, this.parent.pixbufHeight)
		}
	}
	var modelIndex int32
	if this.parent.columnCount == 0 {
		modelIndex = TableFIRST_COLUMN
	} else {
		modelIndex = this.parent.columns[index].modelIndex
	}
	gtk.GTKGtk_list_store_setOverload2(this.parent.modelHandle, this.Handle, modelIndex+TableCELL_PIXBUF, pixbuf, -1)
	if pixbuf != 0 {
		gtk.OSG_object_unref(pixbuf)
	}
	gtk.GTKGtk_list_store_setOverload2(this.parent.modelHandle, this.Handle, modelIndex+TableCELL_SURFACE, surface, -1)
	this.cached = true
	if this.parent.columnCount == 0 {
		column = gtk.GTKGtk_tree_view_get_column(this.parent.Handle, index)
		this.parent.maxWidth = int32(math.Max(float64(this.parent.maxWidth), float64(this.parent.CalculateWidth(column, this.Handle))))
	}
}

