func (this *TableItem) SetTextIndexString(index int32, string_ string) {
	this.CheckWidget()
	if string_ == jrt.NullString {
		this.Error(ERROR_NULL_ARGUMENT)
	}
	if this.strings == (nil) {
		if this._getText(index) == string_ {
			return
		}
	} else {
		if this.GetTextIndex(index) == string_ {
			return
		}
	}
	var count int32 = int32(math.Max(float64(1), float64(this.parent.GetColumnCount())))
	if 0 > index || index > count-1 {
		return
	}
	if 0 <= index && index < count {
		if this.strings == (nil) {
			this.strings = make([]string, count)
		}
		if string_ == this.strings[index] {
			return
		}
		this.strings[index] = string_
	}
	if (string_ != "") && (jrt.StringLength(string_) > ItemTEXT_LIMIT) {
		string_ = fmt.Sprintf("%s%s", jrt.Substring(string_, 0, ItemTEXT_LIMIT-jrt.StringLength(ItemELLIPSIS)), ItemELLIPSIS)
	}
	var buffer []int8 = gtk.ConverterWcsToMbcs(string_, true)
	var modelIndex int32
	if this.parent.columnCount == 0 {
		modelIndex = TableFIRST_COLUMN
	} else {
		modelIndex = this.parent.columns[index].modelIndex
	}
	gtk.GTKGtk_list_store_set(this.parent.modelHandle, this.Handle, modelIndex+TableCELL_TEXT, buffer, -1)
	this.cached = true
	var column int64
	if this.parent.columnCount == 0 {
		column = gtk.GTKGtk_tree_view_get_column(this.parent.Handle, index)
		this.parent.maxWidth = int32(math.Max(float64(this.parent.maxWidth), float64(this.parent.CalculateWidth(column, this.Handle))))
	}
}

func (this *TableItem) setText_(string_ string) {
	this.CheckWidget()
	this.SetTextIndexString(0, string_)
}

